CREATE TABLE IF NOT EXISTS programs(program_id TEXT PRIMARY KEY, name TEXT UNIQUE NOT NULL, department TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS courses(course_id TEXT PRIMARY KEY, program_id TEXT NOT NULL REFERENCES programs(program_id), code TEXT UNIQUE NOT NULL, title TEXT NOT NULL, credits INT NOT NULL CHECK(credits BETWEEN 1 AND 6), course_level INT NOT NULL CHECK(course_level BETWEEN 1 AND 4), is_elective BOOLEAN NOT NULL);
CREATE TABLE IF NOT EXISTS prerequisites(prerequisite_id TEXT PRIMARY KEY, course_id TEXT NOT NULL REFERENCES courses(course_id), prerequisite_course_id TEXT NOT NULL REFERENCES courses(course_id), effective_from DATE NOT NULL, effective_to DATE, CHECK(course_id <> prerequisite_course_id), UNIQUE(course_id,prerequisite_course_id,effective_from));
CREATE TABLE IF NOT EXISTS student_plans(student_plan_id TEXT PRIMARY KEY, student_id TEXT NOT NULL, program_id TEXT NOT NULL REFERENCES programs(program_id), term_id TEXT NOT NULL, year_of_study INT NOT NULL CHECK(year_of_study BETWEEN 1 AND 4), created_at DATE NOT NULL, UNIQUE(student_id,term_id));
CREATE TABLE IF NOT EXISTS registration_interests(interest_id TEXT PRIMARY KEY, student_plan_id TEXT NOT NULL REFERENCES student_plans(student_plan_id), course_id TEXT NOT NULL REFERENCES courses(course_id), term_id TEXT NOT NULL, interest_status TEXT NOT NULL CHECK(interest_status IN ('INTERESTED','REGISTERED','WAITLISTED','WITHDRAWN')), interest_date DATE NOT NULL, eligible BOOLEAN NOT NULL, UNIQUE(student_plan_id,course_id,term_id));
CREATE TABLE IF NOT EXISTS faculty(faculty_id TEXT PRIMARY KEY, name TEXT NOT NULL, department TEXT NOT NULL, max_weekly_hours NUMERIC NOT NULL CHECK(max_weekly_hours > 0), employment_status TEXT NOT NULL CHECK(employment_status IN ('ACTIVE','ON_LEAVE','INACTIVE')));
CREATE TABLE IF NOT EXISTS faculty_skills(faculty_skill_id TEXT PRIMARY KEY, faculty_id TEXT NOT NULL REFERENCES faculty(faculty_id), course_id TEXT NOT NULL REFERENCES courses(course_id), skill_level INT NOT NULL CHECK(skill_level BETWEEN 1 AND 5), effective_from DATE NOT NULL, effective_to DATE, UNIQUE(faculty_id,course_id,effective_from));
CREATE TABLE IF NOT EXISTS availability(availability_id TEXT PRIMARY KEY, faculty_id TEXT NOT NULL REFERENCES faculty(faculty_id), term_id TEXT NOT NULL, day_of_week INT NOT NULL CHECK(day_of_week BETWEEN 0 AND 4), slot_id TEXT NOT NULL, available BOOLEAN NOT NULL, effective_from DATE NOT NULL, effective_to DATE);
CREATE TABLE IF NOT EXISTS rooms(room_id TEXT PRIMARY KEY, building TEXT NOT NULL, room_type TEXT NOT NULL CHECK(room_type IN ('LECTURE','LAB')), capacity INT NOT NULL CHECK(capacity > 0), active BOOLEAN NOT NULL);
CREATE TABLE IF NOT EXISTS historical_enrollments(historical_enrollment_id TEXT PRIMARY KEY, course_id TEXT NOT NULL REFERENCES courses(course_id), term_id TEXT NOT NULL, eligible_students INT NOT NULL, registrations INT NOT NULL, enrolled INT NOT NULL, unmet_demand INT NOT NULL, CHECK(enrolled <= registrations), CHECK(unmet_demand = registrations-enrolled), UNIQUE(course_id,term_id));
CREATE TABLE IF NOT EXISTS sections(section_id TEXT PRIMARY KEY, course_id TEXT NOT NULL REFERENCES courses(course_id), term_id TEXT NOT NULL, section_number INT NOT NULL, room_id TEXT REFERENCES rooms(room_id), day_of_week INT NOT NULL CHECK(day_of_week BETWEEN 0 AND 4), slot_id TEXT NOT NULL, planned_capacity INT NOT NULL CHECK(planned_capacity > 0), forecast_demand INT NOT NULL CHECK(forecast_demand >= 0), status TEXT NOT NULL CHECK(status IN ('PROPOSED','ALLOCATED','PARTIAL','CANCELLED')), UNIQUE(course_id,term_id,section_number));
CREATE TABLE IF NOT EXISTS workload_assignments(workload_assignment_id TEXT PRIMARY KEY, section_id TEXT NOT NULL REFERENCES sections(section_id), faculty_id TEXT NOT NULL REFERENCES faculty(faculty_id), weekly_hours NUMERIC NOT NULL CHECK(weekly_hours > 0), status TEXT NOT NULL CHECK(status IN ('PROPOSED','APPROVED','REJECTED')), assigned_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(section_id,faculty_id));
CREATE TABLE IF NOT EXISTS planning_runs(planning_run_id TEXT PRIMARY KEY, seed BIGINT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, forecast_model TEXT NOT NULL, solver_status TEXT NOT NULL, notes TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS forecasts(forecast_id TEXT PRIMARY KEY, planning_run_id TEXT NOT NULL REFERENCES planning_runs(planning_run_id), course_id TEXT NOT NULL REFERENCES courses(course_id), target_term TEXT NOT NULL, forecast_enrollment INT NOT NULL CHECK(forecast_enrollment >= 0), model_name TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(planning_run_id,course_id,target_term));
CREATE TABLE IF NOT EXISTS unmet_demand(unmet_demand_id TEXT PRIMARY KEY, planning_run_id TEXT NOT NULL REFERENCES planning_runs(planning_run_id), course_id TEXT NOT NULL REFERENCES courses(course_id), target_term TEXT NOT NULL, forecast_demand INT NOT NULL, accommodated INT NOT NULL, unmet INT NOT NULL, reason TEXT NOT NULL, CHECK(unmet = forecast_demand-accommodated));
CREATE TABLE IF NOT EXISTS decision_events(event_id TEXT PRIMARY KEY, planning_run_id TEXT NOT NULL REFERENCES planning_runs(planning_run_id), entity_type TEXT NOT NULL, entity_id TEXT NOT NULL, event_type TEXT NOT NULL, event_time TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, actor TEXT NOT NULL, reason TEXT NOT NULL, payload JSONB NOT NULL DEFAULT '{}'::jsonb);
